-- The Drift — initial Supabase schema. Run once in a fresh project.
create extension if not exists "pgcrypto";
create table categories (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, name text not null, color text not null, in_pie boolean not null default true, sort_order int not null, info_examples text, info_counter text, info_edge text, archived boolean not null default false, created_at timestamptz not null default now());
create index on categories (user_id) where not archived;
create table projects (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, name text not null check (length(btrim(name)) between 1 and 120), archived boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), constraint projects_id_user_unique unique (id,user_id));
create index projects_user_id_idx on projects (user_id);
create unique index projects_user_active_name_unique on projects (user_id,lower(btrim(name))) where not archived;
create table entries (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, project_id uuid, label text, started_at timestamptz not null, ended_at timestamptz not null, note text, source text not null default 'manual' check (source in ('timer','manual','template')), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), constraint entries_project_owner_fkey foreign key (project_id,user_id) references projects(id,user_id) on delete restrict, constraint entry_positive check (ended_at > started_at), constraint entry_sane_length check (ended_at - started_at <= interval '365 days'));
create index on entries (user_id, started_at desc);
create index entries_user_project_started_idx on entries (user_id,project_id,started_at desc) where project_id is not null;
create table entry_allocations (entry_id uuid not null references entries(id) on delete cascade, category_id uuid not null references categories(id), weight numeric(3,2) not null check (weight > 0 and weight <= 1), primary key (entry_id, category_id));
create index on entry_allocations (category_id);
create or replace function check_allocation_invariants() returns trigger language plpgsql as $$ declare n int; total numeric; eid uuid := coalesce(new.entry_id, old.entry_id); begin select count(*), coalesce(sum(weight),0) into n,total from entry_allocations where entry_id=eid; if n=0 then return null; end if; if n>2 then raise exception 'An entry may have at most two categories (got %)',n; end if; if abs(total-1.0)>0.001 then raise exception 'Allocation weights must sum to 1.0 (got %)',total; end if; return null; end $$;
create constraint trigger allocation_invariants after insert or update or delete on entry_allocations deferrable initially deferred for each row execute function check_allocation_invariants();
create table intent_versions (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, effective_from timestamptz not null default now(), steepness numeric(2,1) not null default 1.0 check (steepness>=0 and steepness<=2), note text);
create index on intent_versions (user_id, effective_from desc);
create table intent_ranks (intent_id uuid not null references intent_versions(id) on delete cascade, category_id uuid not null references categories(id), rank int not null check (rank>0), primary key (intent_id,category_id), constraint one_category_per_rank unique (intent_id,rank) deferrable initially deferred);
create table running_timer (user_id uuid primary key references auth.users(id) on delete cascade, label text, started_at timestamptz not null, draft jsonb);
alter table categories enable row level security; alter table projects enable row level security; alter table entries enable row level security; alter table entry_allocations enable row level security; alter table intent_versions enable row level security; alter table intent_ranks enable row level security; alter table running_timer enable row level security;
create policy own_categories on categories for all using (auth.uid()=user_id) with check (auth.uid()=user_id);
create policy projects_select_own on projects for select to authenticated using ((select auth.uid())=user_id);
create policy projects_insert_own on projects for insert to authenticated with check ((select auth.uid())=user_id);
create policy projects_update_own on projects for update to authenticated using ((select auth.uid())=user_id) with check ((select auth.uid())=user_id);
grant select,insert,update on projects to authenticated;
create policy own_entries on entries for all using (auth.uid()=user_id) with check (auth.uid()=user_id);
create policy own_intents on intent_versions for all using (auth.uid()=user_id) with check (auth.uid()=user_id);
create policy own_timer on running_timer for all using (auth.uid()=user_id) with check (auth.uid()=user_id);
create policy own_allocations on entry_allocations for all using (exists(select 1 from entries e where e.id=entry_id and e.user_id=auth.uid()));
create policy own_ranks on intent_ranks for all using (exists(select 1 from intent_versions v where v.id=intent_id and v.user_id=auth.uid()));
create view weighted_minutes with (security_invoker=true) as select e.user_id,a.category_id,date_trunc('day',e.started_at) as day,sum(extract(epoch from (e.ended_at-e.started_at))/60*a.weight) as minutes from entries e join entry_allocations a on a.entry_id=e.id group by 1,2,3;

create or replace function public.update_entry_with_allocations(p_entry_id uuid, p_label text, p_started_at timestamptz, p_ended_at timestamptz, p_note text, p_project_id uuid, p_allocations jsonb) returns void language plpgsql security invoker set search_path = '' as $$ declare v_user_id uuid := (select auth.uid()); v_allocation_count integer; v_distinct_category_count integer; v_owned_category_count integer; v_total_weight numeric; begin if v_user_id is null then raise exception 'You must be signed in to update an entry' using errcode = '42501'; end if; if p_label is null or length(btrim(p_label)) not between 1 and 300 then raise exception 'The activity title must be between 1 and 300 characters' using errcode = '22023'; end if; if p_started_at is null or p_ended_at is null or p_ended_at <= p_started_at then raise exception 'The end time must be later than the start time' using errcode = '22023'; end if; if p_ended_at - p_started_at > interval '365 days' then raise exception 'An entry cannot be longer than 365 days' using errcode = '22023'; end if; if jsonb_typeof(p_allocations) is distinct from 'array' then raise exception 'Category allocations must be an array' using errcode = '22023'; end if; select count(*), count(distinct allocation.category_id), coalesce(sum(allocation.weight), 0) into v_allocation_count, v_distinct_category_count, v_total_weight from jsonb_to_recordset(p_allocations) as allocation(category_id uuid, weight numeric); if v_allocation_count not between 1 and 2 then raise exception 'An entry must have one or two category allocations' using errcode = '22023'; end if; if v_distinct_category_count <> v_allocation_count then raise exception 'Each category may only be used once' using errcode = '22023'; end if; if abs(v_total_weight - 1.0) > 0.001 then raise exception 'Category allocation weights must add up to 1.0' using errcode = '22023'; end if; if exists (select 1 from jsonb_to_recordset(p_allocations) as allocation(category_id uuid, weight numeric) where allocation.weight <= 0 or allocation.weight > 1) then raise exception 'Each category allocation must be greater than 0 and at most 1' using errcode = '22023'; end if; select count(*) into v_owned_category_count from jsonb_to_recordset(p_allocations) as allocation(category_id uuid, weight numeric) join public.categories as category on category.id = allocation.category_id and category.user_id = v_user_id; if v_owned_category_count <> v_allocation_count then raise exception 'One or more categories do not belong to this account' using errcode = '42501'; end if; if p_project_id is not null and not exists (select 1 from public.projects where id = p_project_id and user_id = v_user_id) then raise exception 'The selected project does not belong to this account' using errcode = '42501'; end if; update public.entries set label = btrim(p_label), started_at = p_started_at, ended_at = p_ended_at, note = nullif(btrim(p_note), ''), project_id = p_project_id, updated_at = now() where id = p_entry_id and user_id = v_user_id; if not found then raise exception 'The entry was not found or does not belong to this account' using errcode = '42501'; end if; delete from public.entry_allocations where entry_id = p_entry_id; insert into public.entry_allocations (entry_id, category_id, weight) select p_entry_id, allocation.category_id, allocation.weight from jsonb_to_recordset(p_allocations) as allocation(category_id uuid, weight numeric); end; $$;
revoke execute on function public.update_entry_with_allocations(uuid, text, timestamptz, timestamptz, text, uuid, jsonb) from public, anon;
grant execute on function public.update_entry_with_allocations(uuid, text, timestamptz, timestamptz, text, uuid, jsonb) to authenticated;
grant update on table public.entries to authenticated;
grant select, insert, delete on table public.entry_allocations to authenticated;
